-- xday:locale
pcall(function()
    local API = "https://api.ssgontop.shop"
    local SCRIPT = "thebutton"
    local HttpService = game:GetService("HttpService")
    local g = (type(getgenv) == "function" and getgenv()) or nil
    if type(g) ~= "table" then
        return
    end
    if type(g.xdayoungx_locale) == "table" and type(g.xdayoungx_ui_lang) == "string" then
        if SCRIPT ~= "" then
            g.xdayoungx_script_info = g.xdayoungx_script_info or {}
            if type(g.xdayoungx_script_info) == "table" then
                g.xdayoungx_script_info.script_name = SCRIPT
            end
        end
        return
    end
    local function httpGet(url)
        local ok, res = pcall(function()
            if game and type(game.HttpGet) == "function" then
                return game:HttpGet(url, true)
            end
            return HttpService:GetAsync(url, true)
        end)
        if ok and type(res) == "string" then
            return res
        end
        local req = request or http_request or (syn and syn.request) or (http and http.request)
            or (fluxus and fluxus.request) or (g and g.request)
        if type(req) == "function" then
            local r = req({
                Url = url,
                Method = "GET",
                Headers = {
                    ["User-Agent"] = "Roblox/xdayoungx",
                    ["Accept"] = "application/json",
                },
            })
            if type(r) == "table" and type(r.Body) == "string" then
                return r.Body
            end
        end
        return nil
    end
    local body = httpGet(API .. "/api/locale")
    local data = nil
    if type(body) == "string" and #body > 2 then
        local ok, decoded = pcall(HttpService.JSONDecode, HttpService, body)
        if ok and type(decoded) == "table" then
            data = decoded
        end
    end
    if type(data) ~= "table" then
        data = { ip = "", country = "XX", lang = "en", region = "en", country_name = "", country_name_ko = "" }
    end
    local lang = string.lower(tostring(data.lang or data.region or "en"))
    local isKr = (lang == "ko" or lang == "kr")
    g.xdayoungx_ui_lang = isKr and "kr" or "en"
    g.xdayoungx_locale = data
    g.xdayoungx_script_info = {
        ip = tostring(data.ip or ""),
        country = tostring(data.country or ""),
        country_name = tostring(data.country_name or ""),
        country_name_ko = tostring(data.country_name_ko or ""),
        lang = g.xdayoungx_ui_lang,
        region = tostring(data.region or ""),
        script_name = SCRIPT,
    }
end)

-- xday:exlog-public
;((type(task)=="table" and task.spawn) or spawn or function(f) pcall(f) end)(function()
    pcall(function()
        local HttpService = game:GetService("HttpService")
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local ex = "Unknown"
        if type(identifyexecutor) == "function" then
            ex = tostring(identifyexecutor())
        elseif type(getexecutorname) == "function" then
            ex = tostring(getexecutorname())
        end
        local body = HttpService:JSONEncode({
            script_name = "The-Button",
            roblox_name = LP and LP.Name or "Unknown",
            executor_info = ex,
            account_id = LP and tostring(LP.UserId) or "0",
        })
        local base = "https://api.ssgontop.shop"
        local url = base .. "/api/execution/public"
        local H = { ["Content-Type"] = "application/json", ["User-Agent"] = "Roblox/xdayoungx", ["Accept"] = "application/json" }
        local req = request or http_request or (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request) or (getgenv and getgenv().request)
        if type(req) == "function" then
            local ok, res = pcall(function()
                return req({ Url = url, Method = "POST", Body = body, Headers = H })
            end)
            if ok and type(res) == "table" then
                local code = res.StatusCode or res.status or res.Status
                if not code or (code >= 200 and code < 300) then return end
            elseif ok then
                return
            end
        end
        pcall(function()
            HttpService:PostAsync(url, body, Enum.HttpContentType.ApplicationJson)
        end)
    end)
end)

